        self.archived = set()

    def create(self, doc_id, body):
        if not isinstance(doc_id, str):
            return 400  # invalid_id
        if doc_id in self.store and doc_id not in self.archived:
            return 409  # exists
        self.store[doc_id] = body
        if doc_id in self.archived:
            self.archived.remove(doc_id)
        return 201  # created

    def read(self, doc_id):
        if not isinstance(doc_id, str):
            return (400, None)  # invalid_id
        if doc_id in self.store:
            return (200, self.store[doc_id])
        return (404, None)  # missing

    def put(self, doc_id, body):
        if not isinstance(doc_id, str):
            return 400  # invalid_id
        if doc_id not in self.store:
            return 404  # missing
        if doc_id in self.archived:
            return 409  # archived_put
        self.store[doc_id] = body
        return 200

    def archive(self, doc_id):
        if not isinstance(doc_id, str):
            return 400  # invalid_id
        if doc_id not in self.store:
            return 404  # missing
        self.archived.add(doc_id)
        return 200

    def list(self):
        return sorted(self.store.keys())
